namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryGetOrderQuantity(item, season, out int orderQuantity))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQuantity);
            plan.Add(FormatPlanEntry(item.Sku, orderQuantity, placed));
        }

        return plan;
    }

    private static bool TryGetOrderQuantity(StockItem item, int season, out int orderQuantity)
    {
        orderQuantity = 0;
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return false;

        int deficit = item.ReorderPoint - available;
        orderQuantity = CalculateOrderQuantity(deficit, season);
        return orderQuantity > 0 && !string.IsNullOrEmpty(item.Sku);
    }

    private static int CalculateOrderQuantity(int deficit, int season)
    {
        int orderQuantity = deficit switch
        {
            <= 0 => 0,
            < 10 => 10,
            < 100 => deficit,
            _ => deficit + 50
        };

        if (season == 4 && orderQuantity > 0)
            return (int)(orderQuantity * 1.5);

        return season == 1 ? orderQuantity / 2 : orderQuantity;
    }

    private static string FormatPlanEntry(string sku, int orderQuantity, bool placed)
    {
        if (!placed)
            return $"{sku}:FAILED";

        return orderQuantity > 200
            ? $"{sku}:LARGE:{orderQuantity}"
            : $"{sku}:{orderQuantity}";
    }
}
